def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Number of nanoseconds since the Unix epoch
    :param tz: timezone to convert to, or None for UTC
    :return: Time object
