def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    try:
        from datetime import datetime, timedelta, timezone
    except ImportError:
        raise ImportError("datetime module is not available")

    if not isinstance(nanoseconds, int):
        raise ValueError("nanoseconds must be an integer")

    seconds = nanoseconds // 1_000_000_000
    microseconds = (nanoseconds % 1_000_000_000) // 1_000

    dt = datetime(1970, 1, 1) + timedelta(seconds=seconds, microseconds=microseconds)
    if tz is not None:
        if not isinstance(tz, (timezone, str, None)):
            raise ValueError("tz must be an instance of timezone, str, or None")
        if isinstance(tz, str):
            try:
                tz = timezone(timedelta(hours=int(tz)))
            except ValueError:
                raise ValueError(f"Invalid timezone string: {tz}")
        dt = dt.replace(tzinfo=tz)

    return dt.time()
