    from functools import wraps
    from neo4j import GraphDatabase

    def decorator(func):
        @wraps(func)
        def wrapper(tx, *args, **kwargs):
            try:
                if metadata:
                    tx.last_submitted_query_metadata = metadata
                if timeout is not None:
                    with GraphDatabase.driver(tx.database_name, auth=None).session() as session:
                        session.run(f"SET tx.timeout = {timeout}s")
                result = func(tx, *args, **kwargs)
                return result
            except Exception as e:
                raise e
        return wrapper
    return decorator
