import functools

def unit_of_work(metadata=None, timeout=None):
    """Decorator for transaction functions that allows extra control over how the transaction is carried out.

    :param metadata: Dictionary with metadata to be attached to the executing transaction.
    :type metadata: dict, optional

    :param timeout: Transaction timeout in seconds. Transactions that execute longer than the configured timeout
                    will be terminated by the database.
    :type timeout: float or None, optional
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(tx, *args, **kwargs):
            # Attach metadata to the transaction if provided
            if metadata:
                txmetadata.set(metadata)

            # Set the transaction timeout if provided
            if timeout is not None:
                if timeout < 0:
                    raise ValueError("Timeout should not represent a negative duration.")
                txmetadata.set(timeout=timeout)

            try:
                return func(tx, *args, **kwargs)
            except Exception as e:
                raise e
        return wrapper
    return decorator
```

