def unit_of_work(func=None, metadata=None, timeout=None):
    def decorator(func):
        def wrapper(tx, *args, **kwargs):
            if metadata:
                tx.metadata = metadata
            if timeout is not None and timeout < 0:
                raise ValueError("Timeout should not represent a negative duration")
            if timeout is None:
                timeout = None
            try:
                # Apply the timeout if specified
                if timeout is not None:
                    tx.timeout = timeout
                result = func(tx, *args, **kwargs)
                return result
            except Exception as e:
                # Handle any exceptions that occur during the transaction
                print(f"An error occurred during the transaction: {e}")
                raise
        return wrapper
    return decorator(func) if func else decorator
```

