def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    if not hasattr(self, 'data'):
        raise AttributeError("Record has no 'data' attribute")

    if not isinstance(self.data, dict):
        raise ValueError("Record data must be a dictionary")

    result = []
    if not keys:
        result = list(self.data.values())
    else:
        for key in keys:
            if isinstance(key, int) and key >= 0:
                if key < len(self.data):
                    result.append(self.data[list(self.data.keys())[key]])
                else:
                    raise IndexError("Index out of range")
            elif isinstance(key, str) and key in self.data:
                result.append(self.data[key])
            else:
                raise KeyError("Key not found or invalid index")
    return result
