def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of None; indexes provided that are out of bounds
    will trigger an IndexError.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: IndexError if an out-of-bounds index is specified
    """
    if not keys:
        return self._record

    result = {}
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._record):
                raise IndexError(f"Out-of-bounds index: {key}")
            result[self._keys[key]] = self._record[key]
        elif isinstance(key, str):
            if key not in self._keys:
                result[key] = None
            else:
                result[key] = self._record[self._keys.index(key)]
        else:
            raise TypeError(f"Invalid key type: {type(key)}")

    return result
