def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, with ties (e.g., 0.5) rounded to the nearest even number.

    :param n: A float or integer to be rounded
    :return: The rounded integer
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be an integer or float")

    integer_part = int(n)
    fractional_part = n - integer_part

    if fractional_part == 0.5:
        if integer_part % 2 == 0:
            return integer_part
        else:
            return integer_part + 1
    elif fractional_part == -0.5:
        if integer_part % 2 == 0:
            return integer_part
        else:
            return integer_part - 1
    else:
        return round(n)

