def round_half_to_even(n):
    """
    Rounds a number to the nearest integer, with halfway cases rounded to the nearest even number.

    :param n: The number to round.
    :return: The rounded integer.
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    if n >= 0:
        return int(n + 0.5) if n - floor(n) < 0.5 else int(n)
    else:
        return int(n - 0.5) if n - ceil(n) > -0.5 else int(n)
