def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.

    Args:
        name (str): The name of the subclass to create.
        fields (list): A list of field names for the subclass.
        srid_map (dict): A dictionary mapping field names to SRID values.

    Returns:
        type: A dynamically created subclass of Point.

    Raises:
        ValueError: If any of the field names in fields are not in srid_map.

    """
    if not all(field in srid_map for field in fields):
        raise ValueError("All field names in fields must be in srid_map.")

    class DynamicPoint:
        def __init__(self, **kwargs):
            for field in fields:
                if field in kwargs:
                    setattr(self, field, kwargs[field])
                else:
                    setattr(self, field, None)

        def get_srid(self, field):
            return srid_map.get(field, None)

    return type(name, (DynamicPoint,), {})
