import numbers

class Point:
    @staticmethod
    def from_coordinates(x, y, srid=None):
        if not all(isinstance(coord, numbers.Number) for coord in [x, y]):
            raise ValueError("Coordinates must be numbers")
        return x, y, srid

class PointTypeMeta(type):
    def __new__(cls, name, fields, srid_map, **kwargs):
        for field in fields:
            if field not in srid_map:
                raise KeyError(f"Field '{field}' not found in SRID map")
        return super().__new__(cls, name, fields, srid_map, **kwargs)

class PointType(metaclass=PointTypeMeta):
    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        cls.from_coordinates = Point.from_coordinates

    def __init__(self, *args, **kwargs):
        if len(args) > 2:
            raise ValueError("Too many positional arguments")
        x, y = args
        srid = kwargs.get('srid')
        self.x, self.y, self.srid = Point.from_coordinates(x, y, srid)

# Example usage:
@PointTypeMeta
class CustomPoint(PointType):
    __metaclass__ = PointTypeMeta

    __slots__ = ('x', 'y', 'srid')

    def __init__(self, x, y, srid=None):
        super().__init__(x, y, srid=srid)

# Creating an instance of CustomPoint
point = CustomPoint(1.0, 2.0, srid=4326)
print(point.x, point.y, point.srid)  # Output: 1.0 2.0 4326
