def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """

    if not cmd:
        return cmd

    normalized_cmd = []
    for part in cmd:
        if isinstance(part, str):
            # Replace backslashes with forward slashes
            part = part.replace("\\", "/")
            # Handle deep-path shebangs
            if part.startswith("#!"):
                subsequent_parts = list(cmd)[cmd.index(part) + 1:]
                full_shebang = part
                for sub_part in subsequent_parts:
                    full_shebang += " " + sub_part
                    # Stop if we reach an argument to the shebang
                    if " " in sub_part:
                        break
                normalized_cmd.append(full_shebang)
                continue

        normalized_cmd.append(part)

    return tuple(normalized_cmd)

