def cached(cache, key=hashkey, lock=None):
    def decorator(func):
        if not callable(key):
            raise ValueError("Key must be a callable function")
        if lock is not None and not hasattr(lock, 'acquire') or not hasattr(lock, 'release'):
            raise ValueError("Lock must be None or an object with acquire and release methods")

        def wrapper(*args, **kwargs):
            try:
                cache_key = key(*args, **kwargs)
            except Exception as e:
                raise ValueError("Key function raised an error") from e

            if cache_key in cache:
                return cache[cache_key]

            if lock is not None:
                lock.acquire()

            try:
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
            finally:
                if lock is not None:
                    lock.release()

        return wrapper

    return decorator
