import threading

def cached(cache, key=hash, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            def compute_key(a, kw):
                kw_copy = kw.copy()
                kw_copy.update(zip(func.__annotations__.get(a.__name__, tuple()), a))
                return key(*a, **kw_copy)

            def get_lock():
                if lock is None:
                    return threading.Lock()
                return lock

            with get_lock():
                a = args
                kw = kwargs
                func_key = compute_key(a, kw)

                if func_key in cache:
                    return cache[func_key]

                result = func(*a, **kw)
                cache[func_key] = result
                return result

        return wrapper
    return decorator
