import time
from functools import wraps

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    class TLLEntry:
        __slots__ = ('value', 'timestamp')

        def __init__(self, value):
            self.value = value
            self.timestamp = timer()

        def expired(self):
            return timer() - self.timestamp > ttl

    cache = {}
    cache_info = {'hits': 0, 'misses': 0, 'maxsize': maxsize, 'currsize': 0}

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else (args, tuple(sorted(kwargs.items())))
            cache_key = (id(func), key)

            if cache_key in cache:
                entry = cache[cache_key]
                if entry.expired():
                    del cache[cache_key]
                    cache_info['misses'] += 1
                else:
                    cache_info['hits'] += 1
                    return entry.value
            else:
                cache_info['misses'] += 1

            value = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Least Recently Used eviction
                oldest_key = min(cache, key=lambda k: cache[k].timestamp)
                del cache[oldest_key]
            cache[cache_key] = TLLEntry(value)
            cache_info['currsize'] = len(cache)

            return value

        def cache_clear():
            nonlocal cache
            cache = {}
            cache_info['currsize'] = 0

        def cache_info_():
            return cache_info

        wrapper.cache_clear = cache_clear
        wrapper.cache_info = cache_info_

        return wrapper

    return decorator
