import time
from typing import Any, Callable, Dict, Optional

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """

    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")
    if not isinstance(ttl, int) or ttl < 0:
        raise ValueError("ttl must be a non-negative integer")
    if not callable(timer):
        raise TypeError("timer must be a callable")

    if maxsize == 0:
        # effectively disable caching
        def decorator(func: Callable) -> Callable:
            return func
    else:
        cache: Dict[Any, Dict[str, Any]] = {}
        locks = {}

        def decorator(func: Callable) -> Callable:
            @functools.wraps(func)
            def wrapper(*args: Any, **kwargs: Any) -> Any:
                key = (args, tuple(kwargs.items())) if typed else (tuple(args), frozenset(kwargs.items()))
                lock = locks.get(key)
                if lock is None:
                    lock = threading.Lock()
                    locks[key] = lock
                with lock:
                    entry = cache.get(key)
                    if entry is None:
                        result = func(*args, **kwargs)
                        entry = {
                            'result': result,
                            'expiration': timer() + ttl
                        }
                        cache[key] = entry
                    else:
                        current_time = timer()
                        if current_time >= entry['expiration']:
                            result = func(*args, **kwargs)
                            entry['result'] = result
                            entry['expiration'] = current_time + ttl
                        else:
                            result = entry['result']
                    return result
            return wrapper
        return decorator

    return decorator
