def lfu_cache(maxsize=128, typed=False):
    from collections import defaultdict, OrderedDict
    from functools import wraps

    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = defaultdict(OrderedDict)
            self.frequency = defaultdict(int)
            self.min_freq = 0

        def _wrap_key(self, func, args, kwargs):
            if self.typed:
                return (func, args, tuple(kwargs.items()))
            return args + tuple(kwargs.items())

        def __call__(self, func):
            @wraps(func)
            def wrapper(*args, **kwargs):
                key = self._wrap_key(func, args, kwargs)
                if key in self.cache[self.frequency[key]]:
                    self.cache[self.frequency[key]].move_to_end(key)
                else:
                    self.cache[self.frequency[key]].clear()
                    self.frequency[key] = 1

                if key in self.cache[self.frequency[key]]:
                    value = self.cache[self.frequency[key]][key]
                    self.frequency[key] += 1
                    self.cache[self.frequency[key]][key] = value
                    return value

                if len(self.cache) >= self.maxsize:
                    while not self.cache[self.min_freq]:
                        self.min_freq += 1
                    key_to_remove = next(iter(self.cache[self.min_freq]))
                    del self.cache[self.min_freq][key_to_remove]
                    del self.frequency[key_to_remove]

                value = func(*args, **kwargs)
                self.cache[1][key] = value
                self.frequency[key] = 1
                self.min_freq = 1
                return value

            return wrapper

    return LFUCache(maxsize, typed)
