    class CacheInfo:
        __slots__ = ('hits', 'misses')

        def __init__(self, hits=0, misses=0):
            self.hits = hits
            self.misses = misses

        def __repr__(self):
            return f'CacheInfo(hits={self.hits}, misses={self.misses})'

        def __eq__(self, other):
            if isinstance(other, CacheInfo):
                return (self.hits == other.hits) and (self.misses == other.misses)
            return NotImplemented

    def decorating_function(user_function):
        if maxsize is None:
            return user_function

        func = user_function
        cache = OrderedDict()
        cache_info = CacheInfo()
        _hash_key = functools._make_key

        def lru_cache_wrapper(*args, **kwargs):
            key = _hash_key(args, kwargs, typed)
            try:
                hit = (key in cache)
            except TypeError:
                # not hashable
                hit = False
            if hit:
                cache.move_to_end(key)
                cache_info.hits += 1
            else:
                cache_info.misses += 1
            if hit or len(cache) < maxsize:
                result = func(*args, **kwargs)
                cache[key] = result)
            return result

        def cache_clear():
            nonlocal cache_info
            cache.clear()
            cache_info = CacheInfo()

        def cache_info():
            return cache_info

        def cache_invalidated():
            cache.clear()

        lru_cache_wrapper.cache_clear = cache_clear
        lru_cache_wrapper.cache_info = cache_info
        lru_cache_wrapper.cache_invalidated = cache_invalidated

        functools.update_wrapper(lru_cache_wrapper, func)
        return lru_cache_wrapper

