def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = {}
            self.usage = Counter()
            self.freq_counter = defaultdict(list)

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = self._make_key(args, kwargs) if self.typed else args
                if key in self.cache:
                    self.usage[key] += 1
                    return self.cache[key][0]
                elif len(self.cache) >= self.maxsize:
                    least_freq = self.usage.most_common()[:-2:-1][0][0]
                    least_recent = self.freq_counter[least_freq].pop(0)
                    del self.cache[least_recent]
                    del self.usage[least_recent]
                self.cache[key] = (func(*args, **kwargs), )
                self.usage[key] = 1
                self.freq_counter[1].append(key)
                return self.cache[key][0]

            return wrapper

        def _make_key(self, args, kwargs):
            return args, tuple(sorted(kwargs.items()))

    return LFUCache(maxsize, typed)
