def cachedmethod(cache, key=None, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """

    def decorator(func):
        cache_key = key or (lambda func, args, kw: (func, args, tuple(sorted(kw.items()))))

        def wrapper(self, *args, **kw):
            actual_key = cache_key(func, args, kw)
            try:
                if lock:
                    lock.acquire()
                    try:
                        result = cache.get(actual_key)
                        if result is None:
                            result = func(self, *args, **kw)
                            cache[actual_key] = result
                        return result
                    finally:
                        lock.release()
                else:
                    result = cache.get(actual_key)
                    if result is None:
                        result = func(self, *args, **kw)
                        cache[actual_key] = result
                    return result
            except Exception as e:
                cache.pop(actual_key, None)
                raise e

        return wrapper

    return decorator
