def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    :param classes: List of base classes (list of strings)
    :return: Minimal equivalent list of base classes (list of strings)
    """
    def is_dependency(child, parent):
        """
        Check if 'parent' is a dependency of 'child'
        """
        queue = [child]
        visited = set()
        while queue:
            node = queue.pop(0)
            if node in visited:
                continue
            visited.add(node)
            if node == parent:
                return True
            if node in graph:
                queue.extend(graph[node])
        return False

    graph = {}
    for class_ in classes:
        for other_class in classes:
            if class_ == other_class:
                continue
            if class_.startswith(other_class + '.'):
                if class_ not in graph:
                    graph[class_] = []
                graph[class_].append(other_class)

    minimal = []
    for class_ in classes:
        if not any(is_dependency(class_, other) for other in minimal):
            minimal.append(class_)

    # Create ordered minimal equivalent list
    ordered = []
    while minimal:
        for class_ in minimal[:]:
            if all(not is_dependency(class_, other) for other in minimal if other != class_):
                ordered.append(class_)
                minimal.remove(class_)

    return ordered
