def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    class SuccessorMap:
        def __init__(self, classes):
            self.successors = {cls: set(superclasses) for cls, superclasses in classes.items()}

    def dfs(cls, visited, path):
        if cls in path:
            return []
        if cls in visited:
            return visited[cls]
        path.append(cls)
        cleaned_successors = [s for s in self.successors[cls] if s not in path]
        paths = []
        for s in cleaned_successors:
            paths.extend(dfs(s, visited, path))
        paths.append(cls)
        visited[cls] = paths
        path.pop()
        return paths

    min_basis = []
    for cls in classes:
        path = dfs(cls, {}, [])
        if path:
            path = path[:-1]
            for i in range(len(min_basis)):
                if set(min_basis[i]) <= set(path):
                    break
            else:
                min_basis.append(path)
    return [tuple(path) for path in min_basis]
