def minimalBases(classes):
    # Helper function to calculate the transitive closure of the inheritance graph
    def transitive_closure(cls, closure=None):
        if closure is None:
            closure = set(cls)
        for base in cls.__bases__:
            if base not in closure:
                closure.add(base)
                transitive_closure(base, closure)
        return closure

    # Calculate the transitive closure for each class
    closures = {cls: transitive_closure(cls) for cls in classes}

    # Check for minimal bases
    minimal = []
    for cls in classes:
        if all(any(closure == cls for closure in closures[base]) for base in cls.__bases__ if base not in minimal):
            minimal.append(cls)

    # Sort the minimal bases
    minimal.sort(key=lambda cls: classes.index(cls))

    return minimal
