        raise ValueError("All elements in bins must be numbers.")

    if not all(isinstance(x, (int, float)) for x in edges):
        raise ValueError("All elements in edges must be numbers.")

    if not all(edges[i] < edges[i + 1] for i in range(len(edges) - 1)):
        raise ValueError("Edges must be in ascending order.")

