def difference(d1, d2, level=-1):
    """
    Returns a dictionary with items from d1 not contained in d2.

    :param d1: First dictionary
    :type d1: dict
    :param d2: Second dictionary
    :type d2: dict
    :param level: Maximum depth of recursion, -1 for infinite recursion
    :type level: int
    :return: Dictionary with differences
    :rtype: dict
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise ValueError("Both d1 and d2 must be dictionaries")
    if level is not None and not isinstance(level, int):
        raise ValueError("Level must be an integer or None")

    def helper(sub_d1, sub_d2, current_level):
        if current_level == 0:
            return {}
        result = {}
        for key, value in sub_d1.items():
            if key not in sub_d2:
                result[key] = value
            elif isinstance(value, dict) and isinstance(sub_d2[key], dict):
                diff = helper(value, sub_d2[key], current_level - 1)
                if diff:
                    result[key] = diff
        return result

    return helper(d1, d2, level)

