def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """
    Together with :func:`update_last_applied_manifest_dict_from_resp`, this function
    is called recursively to update a partial ``last_applied_manifest`` from a
    partial Kubernetes response.

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated.
        observer_schema (list): partial ``observer_schema``.
        response (list): partial response from the Kubernetes API.

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.

    """
    if not all(isinstance(item, dict) for item in [last_applied_manifest, observer_schema, response]):
        raise ValueError("All arguments must be lists of dictionaries.")

    for observer in observer_schema:
        key = observer.get("name")
        if key in response:
            value = response[key]
            if key not in last_applied_manifest:
                last_applied_manifest.append({key: value})
            else:
                index = next((i for i, item in enumerate(last_applied_manifest) if item.get("name") == key), None)
                if index is not None:
                    last_applied_manifest[index] = {**last_applied_manifest[index], **value}

    for item in response:
        name = item.get("name")
        if name not in observer_schema:
            last_applied_manifest.append(item)

    return last_applied_manifest
