        item_in_response = next((x for x in response if x.get('key') == item.get('key')), None)

        if item_in_response:
            # If the item is present in the response, update last_applied_manifest
            if item['type'] == 'dict':
                if item['key'] not in last_applied_manifest:
                    last_applied_manifest.append({item['key']: {}})
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[-1][item['key']], item['schema'], item_in_response['value']
                )
            elif item['type'] == 'list':
                if item['key'] not in last_applied_manifest:
                    last_applied_manifest.append({item['key']: []})
                update_last_applied_manifest_list_from_resp(
                    last_applied_manifest[-1][item['key']], item['schema'], item_in_response['value']
                )
            else:
                if item['key'] not in last_applied_manifest:
                    last_applied_manifest.append({item['key']: item_in_response['value']})
        else:
            # If the item is not in the response, initialize its value in last_applied_manifest
            if item['key'] not in last_applied_manifest:
                value = {} if item['type'] == 'dict' else []
                last_applied_manifest.append({item['key']: value})

    return last_applied_manifest
