def format(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(sql, bytes):
        out_sql = bytearray()
    else:
        out_sql = []

    out_params = {}

    if isinstance(params, dict):
        in_style = 'named'
    elif isinstance(params, (list, tuple)):
        in_style = 'ordinal'
    else:
        raise ValueError("Invalid params type. Must be a dict or a sequence.")

    if in_style == 'named':
        for key, value in params.items():
            param_name = f":{key}"
            out_params[key] = value
            out_sql.append(sql.replace(f"%({key})s", param_name))

    elif in_style == 'ordinal':
        for i, value in enumerate(params):
            param_name = f"%({i})s"
            out_params[i] = value
            out_sql.append(sql.replace(f"%({i})s", param_name))

    out_sql = b''.join(out_sql) if isinstance(sql, bytes) else ''.join(out_sql)
    return out_sql, out_params
