import re
from typing import AnyStr, Dict, Union, Sequence, Tuple, TypeVar

T = TypeVar('T', str, bytes)

def format(
    self,
    sql: T,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[T, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(sql, bytes):
        sql_str = sql.decode('utf-8')
    else:
        sql_str = sql

    if isinstance(params, dict):
        param_style = 'named'
        param_pattern = r':(\w+)'
        param_pairs = [(match.group(1), value) for match, value in zip(re.finditer(param_pattern, sql_str), params)]
    elif isinstance(params, list):
        param_style = 'ordinal'
        param_pattern = r'\?'
        param_pairs = [(str(index + 1), value) for index, value in enumerate(params)]
    else:
        raise ValueError("params must be a dictionary for named styles or a sequence for ordinal styles")

    formatted_sql = re.sub(param_pattern, r'\1', sql_str)
    converted_params = {key: value for key, value in param_pairs}

    if isinstance(sql, bytes):
        formatted_sql = formatted_sql.encode('utf-8')

    return formatted_sql, converted_params
