def format(
    self,
    sql: AnyStr,
    params: Union[Dict[Union[str, int], Any], Sequence[Any]],
) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    if isinstance(sql, str):
        result_sql = bytearray()
        param_dict = {} if isinstance(params, dict) else []
        param_index = 0
        i = 0
        while i < len(sql):
            if sql[i] == ':' and i + 1 < len(sql) and sql[i + 1] in '0123456789':
                start = i
                while i + 1 < len(sql) and sql[i + 1] in '0123456789':
                    i += 1
                param_index = int(sql[start + 1:i + 1])
                result_sql.extend(sql[start:i + 1].encode())
                if isinstance(params, list):
                    if param_index - 1 < len(params):
                        param_dict[param_index] = params[param_index - 1]
                    else:
                        param_dict[param_index] = None  # Handle missing parameter
                i += 1
            elif sql[i] == '?':
                result_sql.extend(b'%s')
                if isinstance(params, dict):
                    param_dict['%s'] = params[param_index]
                    param_index += 1
                elif isinstance(params, list):
                    param_dict.append(params[param_index])
                    param_index += 1
                i += 1
            else:
                result_sql.extend(sql[i].encode())
                i += 1
        return result_sql.decode(), param_dict
    else:
        raise ValueError("SQL must be a string or bytes")
