from typing import AnyStr, Union, Iterable, Dict, Sequence, Tuple
from collections.abc import Mapping, Sequence

def formatmany(
    sql: AnyStr,
    many_params: Union[Iterable[Mapping[str, Any]], Iterable[Sequence[Any]]],
) -> Tuple[AnyStr, Union[List[Dict[str, Any]], List[Sequence[Any]]]]:
    if isinstance(sql, str):
        sql_out = sql.replace('?', '${}')
    else:
        sql_out = sql.replace(b'?', b'${}')

    params_out_lists = []
    for params in many_params:
        if isinstance(params, Mapping):
            param_map = {key: params[key] for key in params}
        elif isinstance(params, Sequence):
            param_map = {f'${i+1}': params[i] for i in range(len(params))}
        else:
            raise ValueError("invalid params")
        params_out_lists.append(param_map)

    return sql_out, params_out_lists
