def check_digests_present_and_used(manifest_files, digests_used):
    # Check if manifest_files is a list
    if not isinstance(manifest_files, list):
        raise ValueError("manifest_files must be a list")

    # Check if digests_used is a set
    if not isinstance(digests_used, set):
        raise ValueError("digests_used must be a set")

    # Iterate over each file in the manifest
    for manifest_file in manifest_files:
        # Check if manifest_file is a dictionary
        if not isinstance(manifest_file, dict):
            raise ValueError("Each element in manifest_files must be a dictionary")

        # Get the digests needed from the manifest file
        digests_needed = manifest_file.get("digests", [])

        # Check if digests_needed is a list
        if not isinstance(digests_needed, list):
            raise ValueError("The 'digests' key in each manifest file must be a list")

        # Check if all digests_needed are in digests_used
        for digest in digests_needed:
            if digest not in digests_used:
                raise ValueError(f"Digest {digest} needed but not present in digests_used")

        # Check if any digests in digests_used are not in digests_needed
        for digest in digests_used:
            if digest not in digests_needed:
                raise ValueError(f"Digest {digest} used but not needed in the manifest file for {manifest_file}")

    # If all checks pass
    return True
