def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os
    from collections import defaultdict
    import xml.etree.ElementTree as ET

    if not os.path.isdir(folder):
        raise ValueError("The provided path is not a valid directory")

    grouped_data = defaultdict(list)

    for root, _, files in os.walk(folder):
        for file in files:
            if file.endswith('.xml'):
                file_path = os.path.join(root, file)
                try:
                    tree = ET.parse(file_path)
                    root_element = tree.getroot()
                    data = {child.tag: child.text for child in root_element}
                    base_name = os.path.splitext(file)[0]
                    grouped_data[base_name].append(data)
                except ET.ParseError as e:
                    print(f"Failed to parse {file}: {e}")
                except Exception as e:
                    print(f"Unexpected error occurred while processing {file}: {e}")

    return dict(grouped_data)

def _explore_folder(folder):
    try:
        import os
        import xml.etree.ElementTree as ET

        data_dict = {}

        for filename in os.listdir(folder):
            if filename.endswith('.xml'):
                file_path = os.path.join(folder, filename)
                tree = ET.parse(file_path)
                root = tree.getroot()
                basename = os.path.splitext(filename)[0]
                if basename not in data_dict:
                    data_dict[basename] = []
                data_dict[basename].append(root)

        return data_dict

    except FileNotFoundError:
        print(f"Folder '{folder}' not found.")
        return {}
    except ET.ParseError:
        print(f"Error parsing XML file in folder '{folder}'.")
        return {}
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {}

