            for file_info in zip_ref.infolist():
                if file_info.filename.endswith('.xml'):
                    xml_name = os.path.splitext(file_info.filename)[0]
                    if xml_name in data_dict:
                        data_dict[xml_name].append(zip_ref.open(file_info).read())
                    else:
                        data_dict[xml_name] = [zip_ref.open(file_info).read()]
    except zipfile.BadZipFile:
        raise ValueError(f"The provided path '{zip_path}' is not a valid zip file.")
    except Exception as e:
        raise Exception(f"An error occurred while processing the zip file: {e}")

    return data_dict
