def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    try:
        import sys
        if sys.version_info[0] == 2:
            import codecs
            return lambda *args: codecs.encode(namefunc(*args), 'utf-8')
        else:
            # If it's not Python 2, return the function as is
            return namefunc
    except ImportError:
        raise ImportError("The 'codecs' module is required for this function to work in Python 2.")
