def validate_version_inventories(version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    if not version_dirs:
        raise ValueError("The version_dirs list cannot be empty.")

    root_inventory = None
    content_digests = {}

    for version_dir in version_dirs:
        # Check if each version directory has an inventory
        if not version_dir.endswith('/inventory'):
            raise ValueError(f"Version directory {version_dir} does not have an inventory file.")

        # Load the inventory and compare with the root inventory
        if 'root' in version_dir.lower():
            root_inventory = load_inventory(version_dir)
        else:
            current_inventory = load_inventory(version_dir)
            for key, value in current_inventory.items():
                if key not in root_inventory or root_inventory[key] != value:
                    content_digests[key] = (root_inventory.get(key), current_inventory[key])

    return content_digests
