def validate_version_inventories(version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = {}
    different_digests = []

    for version_dir in version_dirs:
        try:
            version_inventory = load_inventory(version_dir)  # Assume this function loads the inventory for a given version directory

            if not version_inventory:
                raise ValueError(f"No inventory found for version directory: {version_dir}")

            for content_name, content_digest in version_inventory.items():
                if content_name == "@digest":
                    root_digest = content_digest
                elif content_digest != root_digest:
                    different_digests.append((content_name, content_digest))

        except FileNotFoundError:
            print(f"Error: Inventory file not found for version directory: {version_dir}")
        except Exception as e:
            print(f"An error occurred while processing version directory {version_dir}: {e}")

    if different_digests:
        print("Content digests different from those in the root inventory:")
        for content_name, content_digest in different_digests:
            print(f"Content: {content_name}, Digest: {content_digest}")
    else:
        print("All content digests match those in the root inventory.")

    return len(different_digests) == 0

