def validate_version_inventories(self, version_dirs):
    root_inventory = self.load_inventory(version_dirs[0])
    if not root_inventory:
        raise ValueError("No inventory found in the root directory")

    content_digests = set(root_inventory.get('content_digests', []))
    for version_dir in version_dirs[1:]:
        inventory = self.load_inventory(version_dir)
        if not inventory:
            raise ValueError(f"No inventory found in version directory: {version_dir}")

        for digest in inventory.get('content_digests', []):
            if digest not in content_digests:
                content_digests.add(digest)

        # Check if the inventory is up to date
        if inventory['version'] != version_dir:
            raise ValueError(f"Incorrect version number in inventory for directory: {version_dir}")

    return content_digests
