    with open(namaste_path, 'r') as file:
        namaste_content = file.read().strip()

    if namaste_content == 'OCFL_ROOT':
        return 'root'
    elif namaste_content == 'OCFL_OBJECT':
        return 'object'
    elif os.path.isfile(namaste_path):
        return 'file'
    else:
        return 'error: unknown path type'

