def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    :param nodes: List of tuples containing key and value nodes
    :return: List of tuples with merged nodes
    """
    merged = {}
    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged:
            current_value_node = merged[key]
            if isinstance(value_node, ruamel.yaml.nodes.MappingNode) and isinstance(current_value_node, ruamel.yaml.nodes.MappingNode):
                # Recursively merge dictionaries
                merged[key] = deep_merge_dict(current_value_node.value, value_node.value)
            else:
                # Override with the last value if not both are MappingNodes
                merged[key] = value_node
        else:
            merged[key] = value_node

    return [(key_node, value_node) for key_node, value_node in merged.items()]

def deep_merge_dict(base_dict, overlay_dict):
    for k, v in overlay_dict.items():
        if k in base_dict:
            if isinstance(base_dict[k], dict) and isinstance(v, dict):
                # Recursively merge dictionaries
                base_dict[k] = deep_merge_dict(base_dict[k], v)
            else:
                # Override with the last value if not both are dictionaries
                base_dict[k] = v
        else:
            base_dict[k] = v
    return base_dict
