    from ruamel.yaml.nodes import ScalarNode, MappingNode

    result = {}

    for key_node, value_node in nodes:
        key = key_node.value
        if key not in result:
            result[key] = value_node
        else:
            if isinstance(result[key], MappingNode) and isinstance(value_node, MappingNode):
                merged_value = result[key].value
                for sub_key_node, sub_value_node in value_node.value:
                    sub_key = sub_key_node.value
                    merged_value.append((sub_key_node, sub_value_node))
                result[key] = MappingNode(tag='tag:yaml.org,2002:map', value=merged_value)
            else:
                result[key] = value_node

    return [(ScalarNode(tag='tag:yaml.org,2002:str', value=key), value_node) for key, value_node in result.items()]
