def _deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        merged = a.copy()
        for key, value in b.items():
            if key in merged:
                merged[key] = _deep_merge(merged[key], value)
            else:
                merged[key] = value
        return merged
    else:
