    mapping_a_children = {item[0].value: item[1] for item in mapping_a.value}
    mapping_b_children = {item[0].value: item[1] for item in mapping_b.value}

    for key, value in mapping_a_children.items():
        if key in mapping_b_children:
            if isinstance(value, MappingNode) and isinstance(mapping_b_children[key], MappingNode):
                result_value = deep_merge_mapping(value, mapping_b_children[key])
            else:
                result_value = mapping_b_children[key]
        else:
            result_value = value
        result.value.append((ScalarNode(tag='tag:yaml.org,2002:str', value=key), result_value))

    for key, value in mapping_b_children.items():
        if key not in mapping_a_children:
            result.value.append((ScalarNode(tag='tag:yaml.org,2002:str', value=key), value))

    return result
