def deep_merge_nodes(nodes):
    merged_dict = {}

    for key_node, value_node in nodes:
        key_value = key_node.value

        if key_value in merged_dict:
            if isinstance(value_node, ruamel.yaml.nodes.MappingNode) and isinstance(merged_dict[key_value], ruamel.yaml.nodes.MappingNode):
                # Recursively merge dictionaries
                for sub_key_node, sub_value_node in value_node.value:
                    sub_key_value = sub_key_node.value
                    if sub_key_value in merged_dict[key_value].value:
                        # Handle colliding keys by replacing with the new value
                        merged_dict[key_value].value = [
                            (sub_key_node, sub_value_node) if sub_key_value == existing_key.value else existing_item
                            for existing_item, existing_key in enumerate(merged_dict[key_value].value, 0)
                        ]
                    else:
                        merged_dict[key_value].value.append((sub_key_node, sub_value_node))
            else:
                # If colliding keys have non-MappingNode values, keep the last value
                merged_dict[key_value] = value_node
        else:
            merged_dict[key_value] = value_node

    # Convert the merged dictionary back to the input node format
    merged_nodes = [(ruamel.yaml.nodes.ScalarNode(tag='tag:yaml.org,2002:str', value=key), merged_dict[key]) for key in merged_dict]

    return merged_nodes
