                if args:
                    remaining_args.remove(arg)
                    subparser_args.extend(args)
            except SystemExit:
                # argparse raises SystemExit when it encounters an error in parsing
                pass

        parsed_args[subparser_name] = subparser.parse_args(subparser_args)

    return parsed_args, remaining_args

