def size_to_bytes(size: str) -> int:
    size = size.strip()
    if not size:
        raise ValueError("Size string is empty")

    if size[-1] not in '0123456789':
        raise ValueError("Invalid size format")

    value = int(size[:-1])
    multiplier = 1

    if size[-1].upper() == 'K':
        multiplier = 1000
    elif size[-1].upper() == 'M':
        multiplier = 1000000
    elif size[-1].upper() == 'G':
        multiplier = 1000000000
    elif size[-1].upper() == 'T':
        multiplier = 1000000000000

