def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    if len(vertices) < 3:
        raise ValueError("At least 3 vertices are required to form a polygon.")

    result = []
    for i in range(len(vertices)):
        if i == 0:
            result.append((vertices[-1], vertices[0], vertices[1]))  # DAB
        elif i == len(vertices) - 1:
            result.append((vertices[i - 1], vertices[i], vertices[0]))  # CDA
        else:
            result.append((vertices[i - 1], vertices[i], vertices[i + 1]))  # ABC, BCD

    return result

def vertex3tuple(vertices):
    if len(vertices) < 4:
        raise ValueError("There must be at least 4 vertices to form a polygon.")

    result = []
    for i in range(len(vertices)):
        v1 = vertices[i]
        v2 = vertices[(i - 1) % len(vertices)]
        v3 = vertices[(i + 1) % len(vertices)]
        result.append((v2, v1, v3))

    return result

def vertex3tuple(vertices):
    if not isinstance(vertices, list):
        raise ValueError("Input must be a list of vertices")
    if len(vertices) < 4:
        raise ValueError("List must contain at least 4 vertices to form a polygon")

    result = []
    for i in range(len(vertices)):
        prev = vertices[(i - 1) % len(vertices)]
        curr = vertices[i]
        next_ = vertices[(i + 1) % len(vertices)]
        result.append((prev, curr, next_))

    return result

