from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[Path, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive at {archive_path} does not exist.")

    if not os.path.isabs(tmp_path):
        tmp_path = Path(tmp_path).resolve()

    if filename:
        output_path = tmp_path / filename
    else:
        archive_filename = os.path.basename(archive_path)
        output_path = tmp_path / archive_filename.replace(os.path.splitext(archive_filename)[1], "")

    os.makedirs(output_path, exist_ok=True)

    try:
        command = ["tar", "-xzf", archive_path, "-C", str(output_path)]
        if archive_path.endswith('.zip'):
            command = ["unzip", archive_path, "-d", str(output_path)]
        subprocess.run(command, check=True)
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to extract {archive_path}") from e

    return str(output_path)
