def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    import os
    from pathlib import Path
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"The archive path {archive_path} does not exist.")

    if not filename:
        filename = os.path.basename(archive_path)

    temp_dir = Path(tmp_path) / "repo_temp"
    temp_dir.mkdir(parents=True, exist_ok=True)

    try:
        subprocess.run(["unzip", archive_path, "-d", temp_dir], check=True)
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to unzip the archive: {e}")

    repo_url = str(temp_dir / filename)

    if not os.path.exists(repo_url):
        raise Exception(f"The repository URL {repo_url} does not exist after extraction.")

    return repo_url

