        # Split the output into lines
        lines = result.stdout.split('\n')

        # Filter lines to only include ignored files
        ignored_files = [line.split()[1] for line in lines if line and line.split()[0] == '!!']

        # Sort the list of ignored files
        ignored_files.sort()

        # Join the sorted list into a single string with comma-separated filenames
        return ','.join(ignored_files)

    except subprocess.CalledProcessError as e:
        # Return the error message if the git command fails
