import datetime
import re

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    # Regular expression to match frequency string
    pattern = re.compile(r'(\d+)\s*(week[s]?|day[s]?|hour[s]?|minute[s]?)')
    match = pattern.match(frequency)

    if not match:
        raise ValueError("Invalid frequency string")

    number = int(match.group(1))
    unit = match.group(2)

    if unit == 'week' or unit == 'weeks':
        return datetime.timedelta(weeks=number)
    elif unit == 'day' or unit == 'days':
        return datetime.timedelta(days=number)
    elif unit == 'hour' or unit == 'hours':
        return datetime.timedelta(hours=number)
    elif unit == 'minute' or unit == 'minutes':
        return datetime.timedelta(minutes=number)
    else:
        raise ValueError("Unsupported time unit")
