    try:
        if extra_env is None:
            extra_env = {}

        # Construct the command to be run
        command = [func.__module__, func.__name__, *args]

        # Run the command in a subprocess with the specified timeout and environment
        result = subprocess.run(command, timeout=timeout, env={**os.environ, **extra_env}, check=True)

        return result
    except subprocess.CalledProcessError as e:
        # If the subprocess returned a non-zero exit status, raise it
        raise e
    except Exception as e:
        # Handle other exceptions that may have occurred
        raise RuntimeError(f"An error occurred while running the subprocess: {e}") from e

