def subprocess_run_helper(func, *args, timeout, extra_env=None):
    if not callable(func):
        raise ValueError("func must be a callable function")

    try:
        # Prepare the command and environment
        command = [func.__module__, func.__name__] + list(args)
        env = extra_env.copy() if extra_env else {}
        env.update(os.environ)

        # Run the subprocess
        result = subprocess.run(command, env=env, timeout=timeout, check=True, capture_output=True, text=True)
        return result.stdout
    except subprocess.TimeoutExpired:
        raise TimeoutError("Process took longer than the specified timeout")
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Process returned a non-zero exit code: {e}")
    except Exception as e:
        raise RuntimeError(f"An error occurred: {e}")
