def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    # Initialize the final command to be executed
    final_command = commands + ' ' + ' '.join(args)

    # Prepare the subprocess arguments
    subprocess_args = ['bash', '-c', final_command]

    # Set the current working directory if provided
    if cwd is not None:
        subprocess_args['cwd'] = cwd

    # Set the environment if provided
    if env is not None:
        subprocess_args['env'] = env

    # Initialize the stdout and stderr based on the hide_stderr flag
    if hide_stderr:
        stdout = subprocess.PIPE
        stderr = subprocess.DEVNULL
    else:
        stdout = subprocess.PIPE
        stderr = subprocess.PIPE

    # Execute the command using subprocess.run
    try:
        result = subprocess.run(subprocess_args, check=True, stdout=stdout, stderr=stderr, text=True)

        # Check if verbose mode is enabled and print the output if necessary
        if verbose:
            if result.stdout:
                print(result.stdout)
            if result.stderr:
                print(result.stderr)

        return result.stdout.strip()

    except subprocess.CalledProcessError as e:
        if verbose:
            print(f"Error executing command: {e}")
        return f"Error: {e.stderr.strip() if result.stderr else e}"

    except Exception as e:
        if verbose:
            print(f"An unexpected error occurred: {e}")
        return f"Error: {e}"
