from rdflib import Graph, URIRef, Node
from typing import Optional, Set

def find_roots(graph: Graph, prop: URIRef, roots: Optional[Set[Node]] = None) -> Set[Node]:
    if roots is None:
        roots = set()

    nodes_in_hierarchy = set(graph.subjects(predicate=prop))

    new_roots = set()
    for node in nodes_in_hierarchy:
        if all(graph.value(child, prop, node) is None for child in graph.subjects(predicate=prop, object=node)):
            new_roots.add(node)

    roots.update(new_roots)
    if roots != nodes_in_hierarchy:
        roots.update(find_roots(graph, prop, roots))

    return roots
