import configparser

def load_configurations(config_filenames: List[str], overrides: Optional[Dict[str, str]] = None, resolve_env: bool = True) -> Tuple[Dict[str, dict], List[logging.LogRecord]]:
    config_results = {}
    error_log_records = []

    logger = logging.getLogger(__name__)

    if overrides is None:
        overrides = {}

    for config_file in config_filenames:
        config_parser = configparser.ConfigParser()
        try:
            config_parser.read(config_file)
        except Exception as e:
            error_log = logging.LogRecord(level=logging.ERROR, pathname=config_file, lineno=0, msg=f"Error reading configuration file: {e}", args=(), exc_info=None, func=None, extra={})
            error_log_records.append(error_log)
            continue

        config_dict = {section: dict(config_parser.items(section)) for section in config_parser.sections()}

        # Apply overrides
        for key, value in overrides.items():
            if '.' in key:
                section, option = key.split('.')
                if config_dict.get(section, {}).get(option) is not None:
                    config_dict[section][option] = value
            else:
                config_dict[key] = value

        # Resolve environment variables
        if resolve_env:
            for section, options in config_dict.items():
                for option, value in options.items():
                    if value.startswith('${'):
                        value = value[2:-1]
                        try:
                            resolved_value = os.environ[value]
                            config_dict[section][option] = resolved_value
                        except KeyError:
                            error_log = logging.LogRecord(level=logging.WARNING, pathname=config_file, lineno=0, msg=f"Environment variable {value} not found in {config_file}", args=(), exc_info=None, func=None, extra={})
                            error_log_records.append(error_log)
                            config_dict[section][option] = value

        config_results[config_file] = config_dict

    return config_results, error_log_records
