def load_configurations(config_filenames, overrides=None, resolve_env=True):
    import configparser
    import os
    from logging import LogRecord, getLogger, DEBUG, INFO, WARNING, ERROR, CRITICAL, FATAL

    config_dict = {}
    log_records = []

    if overrides is None:
        overrides = {}

    for filename in config_filenames:
        if not os.path.exists(filename):
            log_records.append(LogRecord('load_configurations', ERROR, filename, 0, f"File not found: {filename}", [], None))
            continue

        config = configparser.ConfigParser()
        try:
            config.read(filename)

            # Apply overrides
            for section in config.sections():
                for key, value in overrides.get(section, {}).items():
                    if config.has_option(section, key):
                        config.set(section, key, str(value))

            # Resolve environment variables if applicable
            if resolve_env:
                config.read_dict({section: {key: os.path.expandvars(value) for key, value in config.items(section)} for section in config.sections()})

            config_dict[filename] = {section: dict(config.items(section)) for section in config.sections()}

        except Exception as e:
            log_records.append(LogRecord('load_configurations', ERROR, filename, 0, f"Failed to load configuration: {filename}. Error: {str(e)}", [], None))

    return config_dict, log_records

