def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    import yaml
    from logging import LogRecord

    # Initialize dictionary to store configurations and list to store parse errors
    configurations = {}
    errors = []

    # Load and validate each configuration file
    for filename in config_filenames:
        try:
            with open(filename, 'r') as file:
                config = yaml.safe_load(file)
                if overrides:
                    config = {**config, **overrides}
                if resolve_env:
                    for key, value in config.items():
                        if isinstance(value, str) and value.startswith('env:'):
                            env_var = value.replace('env:', '').strip()
                            config[key] = os.getenv(env_var)
                configurations[filename] = config
        except FileNotFoundError:
            error_message = f"File not found: {filename}"
            logging.error(error_message)
            errors.append(LogRecord('load_configurations', logging.ERROR, None, None, error_message, (), None))
        except yaml.YAMLError as e:
            error_message = f"Error parsing YAML in file: {filename}: {str(e)}"
            logging.error(error_message)
            errors.append(LogRecord('load_configurations', logging.ERROR, None, None, error_message, (), None))
        except Exception as e:
            error_message = f"Unexpected error parsing file: {filename}: {str(e)}"
            logging.error(error_message)
            errors.append(LogRecord('load_configurations', logging.ERROR, None, None, error_message, (), None))

    return configurations, errors
