def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not callable(hist):
        raise ValueError("hist must be a callable representing the histogram")

    if make_value is None:
        make_value = lambda bin_content: bin_content

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if not isinstance(field_names, tuple) or len(field_names) < 1:
        raise ValueError("field_names must be a tuple with at least one element")

    graph_points = []
    for bin_index in range(hist.GetNbinsX() + 1):
        bin_content = hist.GetBinContent(bin_index)
        bin_error = hist.GetBinError(bin_index)

        if make_value is not None:
            try:
                value = make_value(bin_content)
            except Exception as e:
                raise ValueError("make_value function raised an exception") from e
        else:
            value = bin_content

        if get_coordinate == "left":
            coordinate = hist.GetBinLowEdge(bin_index)
        elif get_coordinate == "right":
            coordinate = hist.GetBinLowEdge(bin_index + 1)
        elif get_coordinate == "middle":
            coordinate = hist.GetBinLowEdge(bin_index) + (hist.GetBinWidth(bin_index) / 2)

        graph_points.append((coordinate, *value))

    graph = {field: [point[idx] for point in graph_points] for idx, field in enumerate(field_names)}

    if scale is True:
        graph["scale"] = hist.GetXaxis().GetTitle()

    return graph
