def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if not callable(make_value):
        make_value = lambda bin_content: bin_content

    def get_bin_coordinate(bin_, coord="left"):
        if coord == "left":
            return bin_.bin_left
        elif coord == "middle":
            return (bin_.bin_left + bin_.bin_right) / 2
        elif coord == "right":
            return bin_.bin_right
        else:
            raise ValueError("Invalid get_coordinate value")

    graph_points = []
    for bin_ in hist.bins:
        bin_value = make_value(bin_)
        coord = get_bin_coordinate(bin_, get_coordinate)
        graph_points.append(dict(zip(field_names, (coord,) + bin_value)))

    graph = {
        "points": graph_points,
        "field_names": field_names,
        "scale": bin_.scale if scale is True else scale
    }

    return graph
