def _verify(iface, candidate, tentative=False, vtype=None):
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(f"{candidate} claims to provide {iface}, but it does not.")

    candidate_methods = dir(candidate)
    iface_methods = [attr for attr in dir(iface) if callable(getattr(iface, attr)) and not attr.startswith('_')]
    missing_methods = set(iface_methods) - set(candidate_methods)
    if missing_methods:
        error = f"{candidate} lacks methods: {', '.join(missing_methods)}"
        if len(missing_methods) > 1:
            raise zope.interface.Invalid(error)
        else:
            raise zope.interface.Invalid(missing_methods.pop())

    for method in iface_methods:
        candidate_method = getattr(candidate, method, None)
        if not callable(candidate_method):
            raise zope.interface.Invalid(f"Method {method} is not callable on {candidate}")

    candidate_attrs = dir(candidate)
    iface_attrs = [attr for attr in dir(iface) if not attr.startswith('_')]
    missing_attrs = set(iface_attrs) - set(candidate_attrs)
    if missing_attrs:
        error = f"{candidate} lacks attributes: {', '.join(missing_attrs)}"
        if len(missing_attrs) > 1:
            raise zope.interface.Invalid(error)
        else:
            raise zope.interface.Invalid(missing_attrs.pop())

    return True

