def _verify(iface, candidate, tentative=False, vtype=None):
    try:
        if not tentative and not iface.providedBy(candidate):
            raise zope.interface.Invalid(f"Candidate does not claim to provide interface {iface.__name__}")

        candidate_provides = set(candidate.implementedInterfaces())
        required_methods = {method for method in iface.__dict__ if not method.startswith('_')}
        required_attributes = {attr for attr in iface.__dict__ if not attr.startswith('_')}

        missing_methods = required_methods - candidate_provides
        missing_attributes = required_attributes - candidate_provides

        errors = []

        for method in missing_methods:
            if hasattr(candidate, method):
                candidate_method = getattr(candidate, method)
                if not callable(candidate_method):
                    errors.append(f"Method {method} exists but is not callable")
                else:
                    method_spec = inspect.getfullargspec(candidate_method)
                    method_sig = inspect.signature(candidate_method)
                    expected_sig = inspect.Signature([inspect.Parameter(param, inspect.Parameter.POSITIONAL_OR_KEYWORD) for param in iface[method].__code__.co_varnames[:iface[method].__code__.co_argcount]])
                    if method_sig != expected_sig:
                        errors.append(f"Method {method} has incorrect signature")
            else:
                errors.append(f"Method {method} is missing")

        for attribute in missing_attributes:
            if not hasattr(candidate, attribute):
                errors.append(f"Attribute {attribute} is missing")

        if errors:
            if len(errors) == 1:
                raise zope.interface.Invalid(errors[0])
            else:
                raise zope.interface.Invalid("\n".join(errors))

        return True

    except Exception as e:
        raise zope.interface.Invalid(f"Verification failed: {e}")
    except AttributeError as e:
        raise zope.interface.Invalid(f"Verification failed: {e}")
