def verifyObject(iface, candidate, tentative=False):
    errors = []

    if not tentative:
        if not providedBy(candidate, iface):
            errors.append(f"Candidate does not claim to provide interface: {iface}")

    candidate_methods = dir(candidate)
    iface_methods = [method for method in dir(iface) if callable(getattr(iface, method))]
    missing_methods = [method for method in iface_methods if method not in candidate_methods]
    if missing_methods:
        errors.append(f"Missing methods: {missing_methods}")

    for method in iface_methods:
        candidate_method = getattr(candidate, method)
        iface_method = getattr(iface, method)
        if not callable(candidate_method):
            errors.append(f"Method {method} is not callable in candidate")
        if not callable(iface_method):
            continue  # Not all interface methods need to be callable
        candidate_signature = candidate_method.__code__
        iface_signature = iface_method.__code__
        if candidate_signature.co_argcount != iface_signature.co_argcount:
            errors.append(f"Method {method} has incorrect number of arguments in candidate")
        if candidate_signature.co_varnames != iface_signature.co_varnames:
            errors.append(f"Method {method} has incorrect argument names in candidate")

    missing_attributes = [attr for attr in iface.__dict__ if not hasattr(candidate, attr)]
    if missing_attributes:
        errors.append(f"Missing attributes: {missing_attributes}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        raise Invalid("Multiple errors: " + ", ".join(errors))

    return True

