import zope.interface

def verifyObject(iface, candidate, tentative=False):
    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid(f"Candidate does not claim to provide interface {iface}")

    candidate_methods = set(getattr(candidate, "__dict__", {}).get("__dict__.update", {}))
    required_methods = set(iface.names())

    if candidate_methods != required_methods:
        missing_methods = required_methods - candidate_methods
        if missing_methods:
            raise zope.interface.Invalid(f"Missing methods: {', '.join(missing_methods)}")

    # Signature checks can be complex and are generally handled separately
    # Here we just ensure that all required methods are defined
    for method_name in required_methods:
        method = getattr(candidate, method_name, None)
        if method is None:
