    if explicit_mc is not None:
        return explicit_mc

    # Iterate over bases to find a metaclass
    for base in bases:
        if hasattr(base, '__class__'):
            meta = base.__class__
            if hasattr(meta, '__mro__'):
                return meta

    # Use super() to find the first base with a metaclass
