class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.freq = {}
        self.min_freq = 0

    def get(self, key: int) -> int:
        if key not in self.cache:
            return -1
        freq = self.freq[key]
        value = self.cache[key]
        self.freq[key] = freq + 1
        self.freq[freq].discard(key)
        if not self.freq[freq] and freq == self.min_freq:
            self.min_freq += 1
        if freq + 1 not in self.freq:
            self.freq[freq + 1] = set()
        self.freq[freq + 1].add(key)
        return value

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        if key in self.cache:
            self.get(key)
            self.cache[key] = value
        else:
            if len(self.cache) >= self.capacity:
                evict_key = next(iter(self.freq[self.min_freq]))
                self.freq[self.min_freq].remove(evict_key)
                del self.cache[evict_key]
            self.cache[key] = value
            self.freq[1].add(key)
            self.min_freq = 1

    def popitem(self):
        """Remove and return the (key, value) pair least frequently used."""
        if not self.cache:
            return None
        evict_key = next(iter(self.freq[self.min_freq]))
        evict_value = self.cache[evict_key]
        self.freq[self.min_freq].remove(evict_key)
        del self.cache[evict_key]
        if not self.freq[self.min_freq] and self.min_freq == self.capacity:
            self.min_freq = None
        self.min_freq = min(self.freq.keys()) if self.freq else None
        return (evict_key, evict_value)
