def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    formatted_text = ""

    i = 0
    while i < len(text):
        if text[i:i+3] == "<!--":
            in_code_block = True
            i += 4  # Skip "<!--"
        elif text[i:i+3] == "-->":
            in_code_block = False
            i += 3  # Skip "-->"
        elif not in_code_block and text[i] == '<' and i + 1 < len(text) and text[i+1] != '/':
            start = i
            end = text.find('>', start)
            if end == -1:
                break
            tag = text[start+1:end]
            tags.add(tag)
            i = end + 1
        else:
            if replacer:
                formatted_text += replacer(text[i])
            else:
                formatted_text += text[i]
            i += 1

    return tags, formatted_text

