        if match:
            start, end = pos + match.start(), pos + match.end()
            if not is_within_code_block(text, start):
                tag = match.group()
                tags.add(tag)
                if replacer:
                    result.append(replacer(tag))
                else:
                    result.append(tag)
                pos = end
            else:
                result.append(text[pos:match.start()])
                pos = match.end()
        else:
            result.append(text[pos:])
            pos = len(text)

    return tags, ''.join(result)

