def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def linkify_textual_links(text):
        words = text.split()
        for i, word in enumerate(words):
            if word.startswith('http') or word.startswith('www'):
                try:
                    result = urlparse(word)
                    if result.scheme and result.netloc:
                        words[i] = f'<a href="{word}" target="_blank" rel="noopener noreferrer">{word}</a>'
                except ValueError:
                    # Keep the original word if it's not a valid URL
                    continue
        return ' '.join(words)

    def add_attributes_to_links(text):
        from bs4 import BeautifulSoup
        soup = BeautifulSoup(text, 'html.parser')
        for a_tag in soup.find_all('a'):
            if 'rel' not in a_tag.attrs:
                a_tag['rel'] = 'noopener noreferrer'
        return str(soup)

    processed_text = linkify_textual_links(text)
    processed_text = add_attributes_to_links(processed_text)
    return processed_text

