import json
from typing import Dict
from xml.etree import ElementTree as ET
from urllib.parse import urlparse

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """

    try:
        if document.startswith('{'):
            return parse_json_webfinger(document)
        else:
            return parse_xrd_webfinger(document)
    except (json.JSONDecodeError, ET.ParseError, ValueError) as e:
        raise ValueError("Invalid webfinger document format") from e

def parse_json_webfinger(json_str: str) -> Dict:
    try:
        data = json.loads(json_str)
        subject = data['subject']
        aliases = [alias for alias in data.get('aliases', []) if alias.startswith('acct:')]
        properties = {attr['name']: attr['value'] for attr in data.get('properties', [])}
        return {
            'subject': subject,
            'aliases': aliases,
            'properties': properties
        }
    except (KeyError, TypeError) as e:
        raise ValueError("Malformed JSON webfinger document") from e

def parse_xrd_webfinger(xrd_str: str) -> Dict:
    try:
        root = ET.fromstring(xrd_str)
        subject = root.find('{http://docs.oasis-open.org/ns/xrd-1.0}Subject').text
        aliases = [alias.text for alias in root.findall('{http://docs.oasis-open.org/ns/xrd-1.0}Link[@rel="alternate"][@type="application/json"]')]
        properties = {}
        for prop in root.findall('{http://docs.oasis-open.org/ns/xrd-1.0}Property'):
            name = prop.get('name')
            value = prop.text
            if name and value:
                properties[name] = value
        return {
            'subject': subject,
            'aliases': aliases,
            'properties': properties
        }
    except ET.ParseError as e:
        raise ValueError("Invalid XRD webfinger document") from e
    except (AttributeError, TypeError) as e:
        raise ValueError("Malformed XRD webfinger document") from e
