    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """

    import requests

    if not isinstance(handle, str) or '@' not in handle:
        raise ValueError("Invalid handle. Must be a remote Diaspora handle.")

    try:
        url = f'https://{handle.split("@")[1]}/.well-known/webfinger?resource={requests.utils.quote(handle)}'
        response = requests.get(url)
        response.raise_for_status()

        import xml.etree.ElementTree as ET
        ns = {'jersey': 'http://jersey.java.net/API', 'atom': 'http://www.w3.org/2005/Atom'}
        tree = ET.fromstring(response.content)

