        for link in tree.findall('.//{http://www.w3.org/2005/Atom}link', ns):
            href = link.get('href')
            rel = link.get('rel')
            if href and rel:
                webfinger_data[rel] = href

        return webfinger_data
    except requests.exceptions.RequestException as e:
        raise Exception(f"Failed to retrieve webfinger document for handle {handle}: {e}")
    except ET.ParseError as e:
        raise Exception(f"Failed to parse webfinger document for handle {handle}: {e}")

