def list_of_file_names(settings_dirs, spec_option):
    """
    Create a new IniType complex type

    Parameters:
    settings_dirs (list of str): List of directory paths containing configuration files.
    spec_option (str): Specification option for filtering or processing the configuration files.

    Returns:
    list of str: List of file names extracted from the specified directories based on the given specification option.

    Raises:
    FileNotFoundError: If any of the directory paths in settings_dirs does not exist.
    ValueError: If spec_option is not a valid value.
    """

    if not isinstance(settings_dirs, list) or not all(isinstance(dir, str) for dir in settings_dirs):
        raise ValueError("settings_dirs must be a list of directory paths as strings.")

    if not isinstance(spec_option, str):
        raise ValueError("spec_option must be a string.")

    valid_spec_options = {'option1', 'option2', 'option3'}
    if spec_option not in valid_spec_options:
        raise ValueError(f"Invalid spec_option. Valid options are: {', '.join(valid_spec_options)}")

    file_names = []
    for settings_dir in settings_dirs:
        if not settings_dir:
            continue

        if not os.path.isdir(settings_dir"):
            raise FileNotFoundError(f"The directory path '{settings_dir}' does not exist.")

        try:
            for root, _, files in os.walk(settings_dir):
                for file in files:
                    if file.endswith(".ini"):  # Assuming INI files for demonstration
                        file_names.append(file)
        except Exception as e:
            raise Exception(f"An error occurred while processing directory '{settings_dir}': {str(e)}")

