def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    if not os.path.isdir(plugin_dir):
        raise ValueError("The provided plugin_dir is not a valid directory")

    plugin_spec_path = os.path.join(plugin_dir, 'plugin_spec.json')
    if not os.path.isfile(plugin_spec_path):
        raise FileNotFoundError("The plugin_spec.json file does not exist in the provided directory")

    try:
        with open(plugin_spec_path, 'r') as file:
            plugin_spec = json.load(file)
    except json.JSONDecodeError:
        raise ValueError("The plugin_spec.json file is not a valid JSON")

    flat_dict = {}
    def flatten_dict(d, parent_key='', sep='_'):
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                flatten_dict(v, new_key, sep=sep)
            else:
                flat_dict[new_key] = v

    flatten_dict(plugin_spec)
    return flat_dict
